package com.sertug.Methodlar;

public class operatorler {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
int a = 16;
int b = 44;


System.out.println(a+b);
System.out.println(a-b);
System.out.println(a*b);
System.out.println(a/b);
System.out.println(a%b);


System.out.println(a>b);
System.out.println(a==b);
		
		
		
		
		
		
		
	}

}
